      prof_about:             'بخبرة تمتد لأكثر من عقد في أنظمة الأنابيب الهيدروليكية والبنية التحتية للسباكة السكنية الراقية، أقدم حلولاً هندسية دقيقة للعقارات الفاخرة. حاصل على شهادة من الاتحاد الوطني لأساتذة السباكة، ويجمع نهجي بين الحرفية التقليدية وأحدث تقنيات التشخيص غير الجراحي. متخصص في الكشف السريع عن التسربات، والترميم الشامل للأنابيب، وتركيب تجهيزات الحمامات الفاخرة.',
