      admin_tab_pending_approvals:   'انتظار الموافقة',
      admin_tab_cash_debts:          'الديون النقدية',
      admin_mark_paid:               'تحديد كمدفوع',
      admin_pay_full:                'دفع المبلغ كاملاً',
      admin_partial_payment:         'دفع جزئي',
      admin_outstanding_debt:        'الدين المستحق',
      admin_failed_hold_retry:       'الدفع معلق',
      admin_cash_debt_warning_threshold: 'حد تحذير الدين',
      admin_cash_debt_block_threshold:   'حد إيقاف الدين',
      admin_cash_debt_auto_block:    'إيقاف الفني تلقائياً عند تجاوز الحد',
